<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{FeeRepository,SettingsRepository,StudentRepository};use App\Services\FeeService;use App\Support\Flash;
final class FeesController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function students():StudentRepository{return new StudentRepository($this->app->database());}private function fees():FeeRepository{return new FeeRepository($this->app->database());}private function denied():?Response{return can('fees.view')?null:Response::html('Forbidden',403);}private function month(string$m):bool{return(bool)preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$m);}
public function collect(Request$r):Response{if($x=$this->denied())return$x;$q=trim((string)$r->query('student_query',''));$month=(string)$r->query('month',date('Y-m'));$studentId=(int)$r->query('student_id',0);$selected=$studentId?$this->students()->find($studentId,$this->i()):null;$invoice=null;$items=[];$payments=[];if(!$selected&&$q)$selected=$this->students()->byRegistration($q,$this->i());if($selected&&$this->month($month)){$invoice=$this->fees()->invoice((int)$selected['id'],$month);if($invoice){$items=$this->fees()->items((int)$invoice['id']);$payments=$this->fees()->payments((int)$invoice['id']);}}$raw=$this->app->database()->query('SELECT payment_methods_json FROM fee_settings WHERE institute_id=:i',['i'=>$this->i()])->fetchColumn();$methods=json_decode((string)$raw,true);if(!is_array($methods)||!$methods)$methods=['Cash','Bank','Online Transfer','Cheque','JazzCash','Easypaisa','Other'];return$this->renderPage('fees-collect',['studentResults'=>$this->students()->paginate($this->i(),$q,null,20),'selectedStudent'=>$selected,'selectedMonth'=>$month,'invoice'=>$invoice,'invoiceItems'=>$items,'payments'=>$payments,'paymentMethods'=>$methods,'query'=>$q]);}
public function createInvoice(Request$r):Response{if($x=$this->denied())return$x;$reg=trim((string)$r->input('registration'));$month=(string)$r->input('month');$student=$this->students()->byRegistration($reg,$this->i());if(!$student||!$this->month($month))return Response::html('Invalid student or fee month',422);(new FeeService($this->fees(),$this->students()))->ensureInvoice($student,$this->i(),$month,(int)user()['id']);Flash::add('success','Fee invoice ready.');return Response::redirect(url('/admin/fees/collect?student_query='.rawurlencode($reg).'&month='.$month));}
public function payment(Request$r):Response{if($x=$this->denied())return$x;$reg=trim((string)$r->input('registration'));$month=(string)$r->input('month');$amount=$r->input('payment_amount');$method=(string)$r->input('payment_method');$configured=$this->app->database()->query('SELECT payment_methods_json FROM fee_settings WHERE institute_id=:i',['i'=>$this->i()])->fetchColumn();$methods=json_decode((string)$configured,true);if(!is_array($methods)||!$methods)$methods=['Cash','Bank','Bank Transfer','Online Transfer','Cheque','JazzCash','Easypaisa','Card','Other'];$student=$this->students()->byRegistration($reg,$this->i());if(!$student||!$this->month($month)||!is_numeric($amount)||!in_array($method,$methods,true))return Response::html('Invalid payment details',422);try{$id=(new FeeService($this->fees(),$this->students()))->collect($student,$this->i(),$month,(float)$amount,$method,trim((string)$r->input('reference'))?:null,(int)user()['id']);}catch(\InvalidArgumentException$e){$this->app->session()->flash('_errors',['payment_amount'=>[$e->getMessage()]]);Flash::add('error',$e->getMessage());return Response::redirect(url('/admin/fees/collect?student_query='.rawurlencode($reg).'&month='.$month));}Flash::add('success','Fee payment recorded.');return Response::redirect(url('/admin/fees/receipt/'.$id));}
public function receipt(Request$r):Response{if($x=$this->denied())return$x;$id=(int)$r->route('id');if(!$id)return$this->renderPage('fees-receipt',['receipt'=>null]);$receipt=$this->fees()->receipt($id,$this->i());return$receipt?$this->renderPage('fees-receipt',['receipt'=>$receipt,'items'=>$this->fees()->items((int)$receipt['fee_invoice_id'])]):Response::html('Receipt not found',404);}
public function defaulters(Request$r):Response{if($x=$this->denied())return$x;$month=trim((string)$r->query('month',''));$class=(int)$r->query('class',0);$search=trim((string)$r->query('search',''));$minimum=(float)$r->query('minimum',0);return$this->renderPage('fees-defaulters',['outstanding'=>$this->fees()->outstanding($this->i(),$month,$class,$search,$minimum),'classes'=>(new \App\Repositories\AcademicRepository($this->app->database()))->classes($this->i()),'selectedMonth'=>$month,'selectedClass'=>$class,'search'=>$search,'minimum'=>$minimum]);}
public function report(Request$r):Response{if($x=$this->denied())return$x;return$this->reportPage($r,false);}
public function deleteIndex(Request$r):Response{if($x=$this->denied())return$x;return$this->reportPage($r,true);}
private function reportPage(Request$r,bool$deletion):Response{$month=trim((string)$r->query('month',''));$status=trim((string)$r->query('status',''));$search=trim((string)$r->query('search',''));$rows=$this->fees()->report($this->i(),$month,$status,$search);$totals=['billed'=>0.0,'paid'=>0.0,'remaining'=>0.0];foreach($rows as$row){$totals['billed']+=(float)$row['total_amount'];$totals['paid']+=(float)$row['paid_amount'];$totals['remaining']+=(float)$row['remaining_amount'];}return$this->renderPage($deletion?'fees-delete':'fees-report',['invoices'=>$rows,'totals'=>$totals,'selectedMonth'=>$month,'selectedStatus'=>$status,'search'=>$search,'deletionMode'=>$deletion]);}
public function deleteInvoice(Request$r):Response{if($x=$this->denied())return$x;if((string)$r->input('confirm')!=='delete')return Response::html('Deletion confirmation is required.',422);if(!$this->fees()->deleteInvoice((int)$r->route('id'),$this->i())){Flash::add('error','Invoices with payment history cannot be deleted. Reverse payments and void the invoice instead.');return Response::redirect(url('/admin/fees/delete'));}Flash::add('success','Unused fee invoice deleted.');return Response::redirect(url('/admin/fees/delete'));}
public function reversePayment(Request$r):Response{if($x=$this->denied())return$x;$id=(int)$r->route('id');$reason=trim((string)$r->input('reason'));if($reason===''||!$this->fees()->reversePayment($id,$this->i(),(int)user()['id'],$reason)){Flash::add('error','Payment was not found or is already reversed.');}else{(new \App\Repositories\PakistanErpRepository($this->app->database()))->audit($this->i(),(int)user()['id'],'fee.payment_reversed','fee_payment',$id,['reason'=>$reason]);Flash::add('success','Payment reversed with an audit reason.');}return Response::redirect(url('/admin/fees/report'));}
public function voidInvoice(Request$r):Response{if($x=$this->denied())return$x;$id=(int)$r->route('id');$reason=trim((string)$r->input('reason'));if($reason===''||!$this->fees()->voidInvoice($id,$this->i(),(int)user()['id'],$reason)){Flash::add('error','Only unpaid, active invoices can be voided.');}else{(new \App\Repositories\PakistanErpRepository($this->app->database()))->audit($this->i(),(int)user()['id'],'fee.invoice_voided','fee_invoice',$id,['reason'=>$reason]);Flash::add('success','Invoice voided.');}return Response::redirect(url('/admin/fees/report'));}
}
